    n = 30  # Fixed size for simplicity, can be adjusted if needed
    instances_tested = 0
    total_rank = 0
    conjecture_holds = True
    counterexample = ""

    def generate_disjointness_function(n):
        return [random.randint(0, 1) for _ in range(2**n)]

    def compute_partial_order(f):
        n = len(f)
        poset = [[False] * (2**n) for _ in range(2**n)]
        for i in range(2**n):
            for j in range(2**n):
                if f[i] == 1 and f[j] == 0:
                    poset[i][j] = True
        return poset

    def compute_quandle_representation(poset):
        n = len(poset)
        quandle = {}
        for i in range(n):
            for j in range(i+1, n):
                if poset[i][j]:
                    quandle[(i, j)] = (j, i)
        return quandle

    def compute_minimal_rank(quandle):
        if not quandle:
            return 0
        rank = 1
        while True:
            new_quandle = {}
            for (a, b), (c, d) in quandle.items():
                if c != a and d != b:
                    new_quandle[(a, b)] = (c, d)
            if not new_quandle:
                break
            rank += 1
            quandle = new_quandle
        return rank

    for _ in range(30):
        f = generate_disjointness_function(n)
        poset = compute_partial_order(f)
        quandle = compute_quandle_representation(poset)
        rank = compute_minimal_rank(quandle)
        total_rank += rank
        instances_tested += 1

